/// CERT_LIMIT
pub fn cert_limit(num_players: u8) -> u8 {
    match num_players {
        2 => 40,
        3 => 26,
        4 => 20,
        5 => 16,
        6 => 13,
        7 => 11,
        _ => panic!("1822CA: invalid player count {num_players}"),
    }
}

/// STARTING_CASH
pub fn starting_cash(num_players: u8) -> i32 {
    match num_players {
        2 => 1000,
        3 => 700,
        4 => 525,
        5 => 420,
        6 => 350,
        7 => 300,
        _ => panic!("1822CA: invalid player count {num_players}"),
    }
}

/// BIDDING_TOKENS (keyed by player count)
