/// Major destinations (entities.rb `destination_coordinates`).
pub fn destination(sym: &str) -> Option<&'static str> {
    Some(match sym {
        "CNoR" => "C15",
        "CPR" => "C15",
        "GNWR" => "N16",
        "GT" => "AF12",
        "GTP" => "A7",
        "GWR" => "Z28",
        "ICR" => "AH8",
        "NTR" => "N16",
        "PGE" => "D10",
        "QMOO" => "AA15",
        _ => return None,
    })
}

/// EXCHANGE_TOKENS.
pub fn exchange_tokens(sym: &str) -> u32 {
    match sym {
        "CNoR" => 3,
        "CPR" => 4,
        "GNWR" => 3,
        "GT" => 3,
        "GTP" => 3,
        "GWR" => 3,
        "ICR" => 3,
        "NTR" => 3,
        "PGE" => 3,
        "QMOO" => 3,
        _ => 0,
    }
}

pub fn trains() -> Vec<TrainDef> {
    let t = |name, distance, price, count, rusts_on, events: &'static [&'static str]| TrainDef {
        name,
        distance,
        price,
        count,
        rusts_on,
        multiplier: 1,
        obsolete_on: None,
        events,
        available_on: None,
        discount: &[],
    };
    vec![
        t("L", 1, 60, 22, Some("3"), &[]),
        t("3", 3, 200, 9, Some("6"), &["open_detroit_duluth"]),
        t("4", 4, 300, 6, Some("7"), &[]),
        t("5", 5, 500, 3, None, &["close_concessions"]),
        t("6", 6, 600, 3, None, &["full_capitalisation"]),
        t("7", 7, 750, u32::MAX, None, &["phase_revenue"]),
        t("2P", 2, 0, 2, None, &[]),
        t("LP", 1, 0, 1, None, &[]),
        t("5P", 5, 500, 1, None, &[]),
        t("P", 99, 0, 2, None, &[]),
        t("G", 12, 0, 2, None, &[]),
        // -- variants (no physical cards of their own) --
        TrainDef { available_on: Some("1"), ..t("2", 2, 120, 0, Some("4"), &[]) },
        TrainDef { multiplier: 2, ..t("E", 99, 1000, 0, None, &[]) },
    ]
}

/// The variant a train card may be bought as: (variant name, distance,
/// price, rusts_on).
pub fn train_variant(base: &str, variant: &str) -> Option<(&'static str, u32, i32, Option<&'static str>)> {
    match (base, variant) {
        ("L", "L") => Some(("L", 1, 60, Some("3"))),
        ("L", "2") => Some(("2", 2, 120, Some("4"))),
        ("7", "7") => Some(("7", 7, 750, None)),
        ("7", "E") => Some(("E", 99, 1000, None)),
        _ => None,
    }
}

/// The variants of a base train card (Ruby `train.variants`), base first.
pub fn train_variants(base: &str) -> &'static [&'static str] {
    match base {
        "L" => &["L", "2"],
        "7" => &["7", "E"],
        _ => &[],
    }
}

